statement:
Build a matrix with 2 rows and `n = colsum.length` columns in which every entry is `0` or `1`, such that:

- the entries of row 0 (the upper row) add up to `upper`;
- the entries of row 1 (the lower row) add up to `lower`;
- for every column `i`, its two entries add up to `colsum[i]`.

Return the matrix as a list of its two rows. When several matrices fit, return any one of them; when none fits, return an empty list `[]`.

checker:
function check(input, actual, expected) {
  const [upper, lower, colsum] = input;
  if (!Array.isArray(actual)) return false;
  // When no matrix exists the only accepted answer is an empty list.
  if (expected.length === 0) return actual.length === 0;
  if (actual.length !== 2) return false;
  const [top, bottom] = actual;
  const n = colsum.length;
  if (!Array.isArray(top) || !Array.isArray(bottom) || top.length !== n || bottom.length !== n) return false;
  let topSum = 0;
  let bottomSum = 0;
  for (let i = 0; i < n; i++) {
    if ((top[i] !== 0 && top[i] !== 1) || (bottom[i] !== 0 && bottom[i] !== 1)) return false;
    if (top[i] + bottom[i] !== colsum[i]) return false;
    topSum += top[i];
    bottomSum += bottom[i];
  }
  return topSum === upper && bottomSum === lower;
}

validator:
function validate([upper, lower, colsum]) {
  if (!Array.isArray(colsum) || colsum.length < 1 || colsum.length > 100000) return 'colsum needs 1 to 10^5 values.';
  if (colsum.some(v => v !== 0 && v !== 1 && v !== 2)) return 'Each colsum value is 0, 1 or 2.';
  if (!Number.isInteger(upper) || upper < 0 || upper > colsum.length) return 'upper is a whole number from 0 to colsum.length.';
  if (!Number.isInteger(lower) || lower < 0 || lower > colsum.length) return 'lower is a whole number from 0 to colsum.length.';
  return null;
}

