function reconstructMatrix(upper, lower, colsum) {
  const n = colsum.length;
  const top = new Array(n).fill(0);
  const bottom = new Array(n).fill(0);

  for (let i = 0; i < n; i++) {
    if (colsum[i] === 2) {
      top[i] = 1;
      bottom[i] = 1;
      upper--;
      lower--;
    }
  }
  for (let i = 0; i < n; i++) {
    if (colsum[i] !== 1) {
      continue;
    }
    if (upper > 0) {
      top[i] = 1;
      upper--;
    } else {
      bottom[i] = 1;
      lower--;
    }
  }
  if (upper !== 0 || lower !== 0) {
    return [];
  }
  return [top, bottom];
}

