function reconstructMatrix(upper, lower, colsum) {
  // Try both rows for every column that holds a single 1, and test the row sums at the end.
  const n = colsum.length;
  const top = new Array(n).fill(0);
  const bottom = new Array(n).fill(0);
  const total = row => row.reduce((sum, v) => sum + v, 0);
  const place = col => {
    if (col === n) return total(top) === upper && total(bottom) === lower;
    if (colsum[col] !== 1) {
      top[col] = colsum[col] === 2 ? 1 : 0;
      bottom[col] = top[col];
      return place(col + 1);
    }
    top[col] = 1;
    bottom[col] = 0;
    if (place(col + 1)) return true;
    top[col] = 0;
    bottom[col] = 1;
    return place(col + 1);
  };
  return place(0) ? [top, bottom] : [];
}

