function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const colsum = Array.from({ length: n }, () => Math.floor(rand() * 3));
  const twos = colsum.filter(v => v === 2).length;
  const ones = colsum.filter(v => v === 1).length;
  // Split the single 1s between the rows so a matrix exists, then sometimes break it by one.
  const toTop = Math.floor(rand() * (ones + 1));
  let upper = twos + toTop;
  let lower = twos + ones - toTop;
  const roll = rand();
  if (roll < 0.2) upper += rand() < 0.5 ? 1 : -1;
  else if (roll < 0.35) lower += rand() < 0.5 ? 1 : -1;
  else if (roll < 0.45) [upper, lower] = [upper + 1, lower - 1];
  upper = Math.min(n, Math.max(0, upper));
  lower = Math.min(n, Math.max(0, lower));
  return [upper, lower, colsum];
}
